    assertThat(logMessage.getDataCount(), is(4));
    List<KeyStringValuePair> values = logMessage.getDataList();
    assertThat(values.get(0).getValue(), is("error"));
    assertThat(values.get(1).getValue(), is(RuntimeException.class.getName()));
    assertThat(values.get(2).getValue(), is("exception"));
    assertTrue(values.get(2).getValue().length() <= 4000);
}

@Test
public void testSet() {
    final CorrelationContext context = new CorrelationContext();
    // manual set
    Optional<String> previous = context.put("test1", "t1");
    Assert.assertNotNull(previous);
    Assert.assertFalse(previous.isPresent());
    // set with replace old value
    previous = context.put("test1", "t1New");
    Assert.assertNotNull(previous);
    Assert.assertEquals("t1", previous.get());
    // manual set
    previous = context.put("test2", "t2");
    Assert.assertNotNull(previous);
    Assert.assertFalse(previous.isPresent());
    // out of key count
    previous = context.put("test3", "t3");
    Assert.assertNotNull(previous);
    Assert.assertFalse(previous.isPresent());
    // key not null
    previous = context.put(null, "t3");
    Assert.assertNotNull(previous);
    Assert.assertFalse(previous.isPresent());
    // out of value length
    previous = context.put(null, "123456789");
    Assert.assertNotNull(previous);
    Assert.assertFalse(previous.isPresent());
}

